  'to install openGym as a full-screen app.': "per instal·lar openGym com a aplicació a pantalla completa.",
  'Your data syncs with your profile. Sign in anywhere and it’s there.': "Les teves dades se sincronitzen amb el teu perfil. Inicia la sessió des de qualsevol dispositiu i les tindràs disponibles.",
