  "Best estimate from {0} on {1}. An estimate, not a tested max.": "Millor estimació a partir de {0}, el {1}. És una estimació, no un màxim comprovat.",
  'From your log:': 'Segons el teu registre:',
  "{0} × {1} on {2}": "{0} × {1} el {2}",
  "Estimate": "Estimació",
  "Enter a weight and 1–{0} reps. Beyond that it’s basically guesswork.": "Introdueix un pes i entre 1 i {0} repeticions. Per sobre d'aquest valor, l'estimació és poc fiable.",
  'Best estimated 1RM:': 'Millor 1RM estimat:',
  "Time": "Temps",
  "Seconds": "Segons",
  "A timer runs while you hold the set. Leave the weight at 0 for bodyweight holds.": "Un temporitzador funciona mentre mantens la posició. Deixa el pes a 0 per als exercicis isomètrics amb el pes corporal.",
  "Done": "Fet",
  "Start set": "Comença la sèrie",
