  'Name it after where you train (like "Home" or "Gym"), then tick what you’ve got there.': "Posa-li el nom del lloc on entrenes (com ara «Casa» o «Gimnàs») i marca el material que hi tens.",
  'Profile name': "Nom del perfil",
  'Body-weight exercises are always available, unless they need a pull-up bar or a bench.': "Els exercicis amb pes corporal sempre estan disponibles, tret que necessitin una barra de dominades o un banc.",
