  'Disconnected. Back to local-only': "Desconnectat. S’ha tornat al mode només local",
  'Connect to my server': "Connecta amb el meu servidor",
  'Sync this device to your own self-hosted openGym instead.': "Sincronitza aquest dispositiu amb la teva pròpia instal·lació d’openGym.",
  'Pair the mobile app': "Vincula l’aplicació mòbil",
  'Connect the openGym app on your phone to this account.': "Connecta l’aplicació openGym del telèfon amb aquest compte.",
  'On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.': "A l’aplicació openGym, tria «Connecta amb el meu servidor» i introdueix aquesta adreça i el codi següent. El codi caduca al cap de 5 minuts.",
