  'A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.': "Una sessió rodona: has completat tot el que estava previst i has mantingut les càrregues. Així és com es construeix el progrés: sense grans gestos, però amb constància.",
  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': "Has completat gairebé tota la feina. Una o dues sèries han quedat per sota del previst, cosa que no és cap problema puntualment. Només serà un senyal d’alerta si torna a passar amb les mateixes sèries a la pròxima sessió.",
