  'The server cannot be reached': "No es pot contactar amb el servidor",
  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': "No es pot contactar amb el teu servidor. Els canvis es desen en aquest dispositiu i se sincronitzaran quan el servidor torni a respondre.",
  'Your server can’t be reached. Showing the last copy synced with it.': "No es pot contactar amb el teu servidor. Es mostra l’última còpia sincronitzada amb aquest servidor.",
  'Server address unknown': "Adreça del servidor desconeguda",
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': "Torna a vincular el dispositiu o exporta primer una còpia de seguretat. Si continues igualment, es conservarà una còpia d’aquests canvis en aquest dispositiu fins que es torni a connectar a aquest servidor amb aquest compte. Aleshores, els canvis s’hi tornaran a afegir.",
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': "Torna a iniciar la sessió o exporta primer una còpia de seguretat. Si continues igualment, es conservarà una còpia d’aquests canvis en aquest dispositiu fins que es torni a connectar a aquest servidor amb aquest compte. Aleshores, els canvis s’hi tornaran a afegir.",
  '{0} set · {1} work': "{0} sèrie · {1} de treball",
  'Every exercise in this workout': "Tots els exercicis d’aquest entrenament",
  'No sets are left in this workout, so there is nothing to save. Delete it from your history?': "No queda cap sèrie en aquest entrenament i, per tant, no hi ha res per desar. Vols eliminar-lo de l’historial?",
  // --- a custom exercise's own photo, GIF or video, and its link ---
  'Photo, GIF or video': "Fotografia, GIF o vídeo",
  'Optional. A picture makes it easier to spot in a list.': "Opcional. Una imatge facilita identificar-lo en una llista.",
  'Add': "Afegeix",
  'Change': "Canvia",
  'Video or guide link (optional)': "Enllaç a un vídeo o una guia (opcional)",
  'That link is not a web address': "Aquest enllaç no és una adreça web vàlida",
  'Watch video': "Mira el vídeo",
  'Open link': "Obre l’enllaç",
  'Plays from YouTube, and only once you tap': "Es reprodueix des de YouTube i només quan hi toques",
  'Opens in YouTube': "S’obre a YouTube",
  'That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.': "Aquest tipus de fitxer no és compatible. Fes servir una fotografia, un GIF o un vídeo MP4, MOV o WebM.",
  'That file is too big. Max {0} MB.': "Aquest fitxer és massa gran. El màxim és de {0} MB.",
  'That video is too long. Max {0} seconds.': "Aquest vídeo és massa llarg. La durada màxima és de {0} segons.",
  'That photo is too large to process on this device.': "Aquesta fotografia és massa gran per processar-la en aquest dispositiu.",
  'You’re offline. Try again once you’re back online.': "No tens connexió. Torna-ho a provar quan recuperis la connexió.",
  'This browser cannot read that file.': "Aquest navegador no pot llegir aquest fitxer.",
  'There is no room left on this device for that file.': "No queda prou espai en aquest dispositiu per desar aquest fitxer.",
  'This video may not play on every device. MP4 (H.264) plays everywhere.': "És possible que aquest vídeo no es reprodueixi en tots els dispositius. El format MP4 (H.264) és compatible amb tots.",
  'Your photo and video space on the server is full ({0} of {1} MB).': "L’espai per a fotografies i vídeos del servidor està ple ({0} de {1} MB).",
  'The server refused the file as too large.': "El servidor ha rebutjat el fitxer perquè supera la mida màxima permesa.",
  'Kept on this device only. Export with photos & videos keeps a copy.': "Només es conserva en aquest dispositiu. En exportar les dades amb fotografies i vídeos, també se'n desa una còpia.",
  'Your server does not store photos and videos yet.': "El teu servidor encara no desa fotografies ni vídeos.",
  'This browser cannot store photos or videos here.': "Aquest navegador no pot desar fotografies ni vídeos aquí.",
  'Photos & videos': "Fotografies i vídeos",
  '{0} of {1} MB used on your server': "Has utilitzat {0} de {1} MB al servidor",
  '{0} waiting to upload': "{0} pendents de pujar",
