  'Without photos and videos': "Sense fotografies ni vídeos",
  'Name it and pick a body part. It works just like any other exercise.': "Posa-li un nom i tria una part del cos. Funciona com qualsevol altre exercici.",
  'name + body part, and a photo or video if you like': "nom + part del cos i, si vols, una fotografia o un vídeo",
