  '{0} photos': "{0} fotografies",
  'Your server was reached, but it refused the app’s request (CORS). If a reverse proxy such as Traefik adds CORS headers, let requests from {0} through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': "S’ha pogut contactar amb el teu servidor, però ha rebutjat la petició de l’aplicació (CORS). Si un proxy invers com Traefik afegeix capçaleres CORS, permet que les peticions de {0} arribin a openGym sense modificar-les. Consulta «Phone app and CORS» a docs/SELF_HOSTING.md.",
  'Could not reach {0}. Check the address and that this phone can reach it.': "No s’ha pogut contactar amb {0}. Comprova l’adreça i que aquest telèfon hi tingui accés.",
  'The end of a rest or a hold buzzes like an alarm, even in silent mode.': "Quan acaba un descans o una contracció isomètrica, el telèfon vibra com una alarma, fins i tot en mode silenciós.",
