  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': "openGym ja no pot desar fitxers a «{0}», així que les còpies es tornaran a desar a Documents/openGym. Torna a seleccionar la carpeta per recuperar la ubicació anterior.",
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': "openGym ja no pot desar fitxers a la carpeta seleccionada, així que les còpies es tornaran a desar a Documents/openGym. Torna a seleccionar la carpeta per recuperar la ubicació anterior.",
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': "Avisa’m quan em salti un entrenament planificat",
  'Nudge tone': "To de l’avís",
  "Friendly": "Amable",
  'Guilt trip': "Fer sentir culpable",
  'Drill sergeant': "Sergent instructor",
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': "Un avís al vespre d’un dia planificat en què no hagis registrat cap entrenament, entre les 20.00 i les 21.30. Després de 3 dies seguits sense entrenar, deixarà d’avisar fins al pròxim entrenament.",
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': "Has registrat un entrenament en un altre dispositiu? Abans d’enviar l’avís, el telèfon consulta el servidor sempre que el sistema permet que l’aplicació funcioni en segon pla. En obrir l’aplicació, la informació sempre s’actualitza.",
  'Everything okay?': "Tot bé?",
  '{0} is still waiting. What’s up?': "{0} encara t’espera. Què ha passat?",
  'No {0} today? Even a short session tomorrow counts.': "Avui no toca {0}? Demà, fins i tot una sessió curta compta.",
  'Rough day? {0} will keep. Tomorrow is a fresh start.': "Has tingut un dia difícil? {0} pot esperar. Demà serà un nou començament.",
  'Hey, {0} didn’t happen today. All good?': "Ei, avui no has fet {0}. Tot bé?",
  'I miss you': "Et trobo a faltar",
  '{0} waited by the door all evening. For you.': "{0} t’ha estat esperant a la porta tota la tarda. A tu.",
  'The barbell asked about you today. I didn’t know what to say.': "Avui la barra ha preguntat per tu. No he sabut què dir-li.",
  'Was it something I said? {0} misses you.': "He dit alguna cosa que no t’ha agradat? {0} et troba a faltar.",
  'I saved you a spot on the bench. It’s still empty.': "T’he reservat un lloc al banc. Encara és buit.",
  'Attention, recruit!': "Atenció, recluta!",
  "Your gains are packing their bags. {0} tomorrow, no excuses!": "Els teus progressos estan fent les maletes. Demà toca {0}, sense excuses!",
  '{0} doesn’t do itself, recruit. Move it!': "{0} no es fa sol, recluta. Som-hi!",
  'Excuses don’t lift weights. Report for {0} tomorrow!': "Les excuses no aixequen peses. Demà et vull a {0}!",
  "Your muscles filed a missing-person report. Show up for {0}!": "Els teus músculs han denunciat que has desaparegut. Presenta't a {0}!",
  'That address answers, but it isn’t an openGym server. Check the URL.': "Aquesta adreça respon, però no correspon a un servidor openGym. Comprova l’URL.",
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': "Aquesta adreça respon, però en lloc d’openGym ha contestat una pàgina d’inici de sessió o una regla del servidor intermediari. Permet que les peticions a /api/ arribin a openGym sense modificar-les. Consulta «Phone app and CORS» a docs/SELF_HOSTING.md.",
  'Switch sides': "Canvia de costat",
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': "Desa una còpia amb data a «{0}» quan acabes un entrenament o edites una rutina, i conserva les {1} còpies més recents.",
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': "Desa una còpia amb data a la carpeta que has triat quan acabes un entrenament o edites una rutina, i conserva les {0} còpies més recents.",
