  'Effort per set is off. Turn it on in Settings → Workout to keep rating.': "L’esforç per sèrie està desactivat. Activa’l a Configuració → Entrenament per continuar valorant-lo.",
  'Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.': "Introdueix el codi que mostra l’altre dispositiu a Configuració → Compte → Afegeix un altre dispositiu. Aleshores, aquest dispositiu tindrà la seva pròpia clau d’accés.",
  'Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.': "Obre Configuració → Compte → «Vincula l’aplicació mòbil» al lloc web d’openGym on ja has iniciat la sessió. Després, introdueix-ne l’adreça i el codi que hi apareix.",
  'Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.': "Obre Configuració → Compte → «Vincula l’aplicació mòbil» al lloc web d’openGym des d’un navegador i introdueix-hi el codi nou que hi apareix. Les dades conservades en aquest telèfon es fusionaran amb el teu compte.",
