  'That took a little too long. Give it another go.': "Això ha trigat una mica massa. Torna-ho a provar.",
  "This server only takes changes made at {0}. If you opened openGym at another address, whoever runs the server can set ORIGIN and RP_ID to match it (the self-hosting guide shows how).": "Aquest servidor només accepta canvis fets des de {0}. Si has obert openGym des d’una altra adreça, la persona que administra el servidor pot configurar ORIGIN i RP_ID perquè hi coincideixin (la guia d’allotjament propi explica com fer-ho).",
  'That code didn’t work. Codes last 5 minutes and work once, so grab a fresh one.': "Aquest codi no ha funcionat. Els codis caduquen al cap de 5 minuts i només es poden fer servir una vegada. Demana’n un de nou.",
