  'Options: copy, remove': "Opcions: copia, elimina",
  "Another device synced while you were importing, so its changes were kept next to the backup.": "Un altre dispositiu s’ha sincronitzat mentre importaves les dades. Per això, els seus canvis s’han conservat al costat de la còpia de seguretat.",
  'Save as a backup file': "Desa com a fitxer de còpia de seguretat",
  'Add this device\'s plan to your profile?': "Vols afegir al teu perfil el pla d’aquest dispositiu?",
  'Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': "El pla, les notes o les targetes del gimnàs d’aquest dispositiu es van configurar sense iniciar la sessió. Pots afegir-los al teu perfil o mantenir-lo exactament tal com està al servidor.",
  '{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.': "S’ha creat {0} rutina en aquest dispositiu sense iniciar la sessió. Pots afegir-la al teu perfil o mantenir-lo exactament tal com està al servidor.",
  '{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': "S’han creat {0} rutines en aquest dispositiu sense iniciar la sessió. Pots afegir-les al teu perfil o mantenir-lo exactament tal com està al servidor.",
  'This device, before signing in': "Aquest dispositiu, abans d’iniciar la sessió",
