  'A touch darker in light mode, so you can still read it.': "Una mica més fosc en mode clar perquè es pugui continuar llegint.",
  'Greys show lighter in dark mode, so buttons don’t look switched off.': "Els tons grisos es mostren més clars en mode fosc perquè els botons no semblin desactivats.",
  'Greys show darker in light mode, so buttons don’t look switched off.': "Els tons grisos es mostren més foscos en mode clar perquè els botons no semblin desactivats.",
  'custom color picker': "selector de color personalitzat",
  'Signed in from another tab. Your workout came along, keep going here.': "Has iniciat la sessió des d’una altra pestanya. L’entrenament també s’ha traslladat aquí; pots continuar.",
  'Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.': "El protocol http:// no està xifrat. És acceptable a la xarxa domèstica, però fes servir https:// si es pot accedir al servidor des d’internet.",
  'Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.': "No s’ha pogut contactar amb {0} mitjançant https://. Si el servidor fa servir http sense xifrar (força habitual a casa), introdueix http://{0} en lloc d’això.",
