  'Only if your server is behind Cloudflare Access: the service token this phone sends with every request to it. Kept in this phone’s secure storage.': "Només si el teu servidor està protegit per Cloudflare Access: el testimoni de servei que aquest telèfon envia amb cada petició. Es desa a l’emmagatzematge segur del telèfon.",
