  'As entered': "Tal com s’ha introduït",
  'Each': "Cadascuna",
  'Both': "Totes dues",
  'Weight means': "El pes indica",
  "The weight of the one you hold. One arm, so it counts once.": "El pes de la manuella que subjectes. Com que només n’agafes una, es compta una sola vegada.",
  'The weight of one, so 20 means 20 in each hand. Volume counts both.': "El pes d’una sola manuella; per tant, 20 vol dir 20 a cada mà. El volum compta totes dues.",
  'Both together, so 40 means two 20s.': "El pes de totes dues juntes; per tant, 40 vol dir dues manuelles de 20.",
  'Counted as you type it, the way it always was.': "Es compta tal com l’introdueixes, com s’ha fet sempre.",
  // --- dumbbell inventory (#376) ---
  "You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.": "Has superat el pes màxim del teu joc de manuelles: {0} {1} és la més pesada que tens, així que la càrrega es manté.",
  'Dumbbells': "Manuelles",
  'The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.': "Els pesos de les manuelles que tens, indicats individualment. La progressió, les descàrregues, els escalfaments i els botons + i − dels exercicis amb manuelles només utilitzen aquests pesos.",
  'No list yet, so dumbbell lifts step by their increment as usual.': "Encara no hi ha cap llista; per tant, els exercicis amb manuelles augmenten segons l’increment habitual.",
  'Fill in {0} to {1} {2}, every {3}': "Omple de {0} a {1} {2}, cada {3}",
  'Clear the list': "Buida la llista",
  'Any weight. Tap to list the ones you own.': "Qualsevol pes. Toca per indicar quines manuelles tens.",
  // --- sets to failure (v1.4.0) ---
  'F': "F",
  'Taken to failure': "Fins a la fallada muscular",
  "Nothing left in the tank": "No et queden forces",
  'Last set to failure': "Última sèrie fins a la fallada",
  "The last set goes until nothing is left, and counts as all-out effort unless you rate it.": "L’última sèrie es fa fins que no puguis més i es considera un esforç màxim, tret que n’indiquis una valoració diferent.",
  'Plan the final set as an all-out one.': "Programa l’última sèrie com un esforç màxim.",
  // --- triple progression (issue #179) ---
  'Triple progression': "Progressió triple",
  "Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.": "Les repeticions augmenten fins al límit superior del rang. Aleshores s’afegeix una sèrie, fins a arribar al nombre màxim. Quan totes les sèries arriben al límit superior, augmenta el pes i es torna al nombre inicial de sèries i repeticions.",
  'Same weight, aim for {0} reps in every set.': "Mantén el mateix pes i intenta fer {0} repeticions a cada sèrie.",
  'Same weight, aim for {0} reps on the last set.': "Mantén el mateix pes i intenta fer {0} repeticions a l’última sèrie.",
  '{0} reps in every set! Add a set at {1} reps.': "{0} repeticions a totes les sèries! Afegeix una sèrie de {1} repeticions.",
  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "Has assolit el límit superior en les {0} sèries. Augmenta la càrrega en {1} {2} i torna a {3} sèries de {4}.",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "Has assolit el límit superior en les {0} sèries. Redueix l’assistència en {1} {2} i torna a {3} sèries de {4}.",
  'Short of the target, but more reps than before. Same sets and reps again.': "No has assolit l’objectiu, però has fet més repeticions que abans. Repeteix el mateix nombre de sèries i repeticions.",
  'Missed reps last time. Same sets and reps again ({0} of {1} to go).': "L’última vegada no vas completar totes les repeticions. Repeteix el mateix nombre de sèries i repeticions (en falten {0} de {1}).",
  'Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.': "Fa {0} entrenaments que no avances. Redueix la càrrega a {1} {2} i torna a començar amb {3} sèries de {4}.",
  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "Fa {0} entrenaments que no avances. Torna a fer servir {1} {2} d’assistència i comença de nou amb {3} sèries de {4}.",
  'Sets from': "Sèries des de",
