  // --- collapse completed exercises (#241) ---
  'Fold away': "Replega",
  'Show the sets': "Mostra les sèries",
  'In List and Compact, a finished exercise folds into one line.': "Als modes Llista i Compacte, els exercicis completats es repleguen en una sola línia.",
  // --- day notes (#261) ---
  'Sick': "Malaltia",
