  'Make the box smaller': "Fes el quadre més petit",
  // --- progress photos: remove ---
  'Photo removed': "Foto eliminada",
  // --- set-specific rest ---
  "A breather after one side, before the other. The full rest comes once both sides are done.": "Un descans breu després de fer un costat i abans de fer l’altre. El descans complet comença quan has acabat tots dos costats.",
  'Like the work sets': "Com les sèries de treball",
  'No timer': "Sense temporitzador",
  'Pick a time': "Tria una durada",
  'Rest between sides': "Descans entre costats",
  'Rest between warm-ups': "Descans entre sèries d’escalfament",
  "Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.": "Les sèries d’escalfament són lleugeres, així que poden tenir un descans més curt o no tenir-ne cap. Després de l’última, però, sempre hi ha el descans complet abans de la primera sèrie de treball.",
  // --- progress photos for any day (#557) ---
  'Add photos': "Afegeix fotos",
  'Each photo goes on the day it was taken.': "Cada foto s’afegeix al dia que es va fer.",
  'No progress photos yet. Add one for today or any day before.': "Encara no hi ha fotos de progrés. Afegeix-ne una d’avui o de qualsevol dia anterior.",
  'The photo says it was taken on {0}. Change the day if it was another one.': "La foto indica que es va fer el dia {0}. Canvia la data si es va fer un altre dia.",
  'They all go on the day below.': "Totes s’afegiran al dia que indiquis a continuació.",
  'Which day is this photo from?': "De quin dia és aquesta foto?",
  'Your server keeps photos only on days with a workout. An update lets it keep them for any day.': "El teu servidor només desa fotos dels dies que hi ha hagut un entrenament. Una actualització permetrà desar-les qualsevol dia.",
  'Add {0} photo': "Afegeix {0} foto",
  'Add {0} photos': "Afegeix {0} fotos",
  '{0} photo added': "S’ha afegit {0} foto",
  '{0} photos added': "S’han afegit {0} fotos",
  '{0} photo knows its day and goes there. The others go on the day below.': "La foto {0} ja té la seva data i s’afegirà al dia corresponent. Les altres s’afegiran al dia que indiquis a continuació.",
  '{0} photos know their day and go there. The others go on the day below.': "Les {0} fotos ja tenen la seva data i s’afegiran als dies corresponents. Les altres s’afegiran al dia que indiquis a continuació.",
  // --- progress photos card ---
  "Every progress photo, lined up by date, for any day. Plus a before/after slider.": "Totes les fotos de progrés, ordenades per data, de qualsevol dia. També inclou un control lliscant per comparar l’abans i el després.",
  // --- routine backups ---
  'Add a backup': "Afegeix una alternativa",
  'Backups': "Alternatives",
  'Backups for {0}': "Alternatives per a {0}",
  'Everything else': "La resta",
  "Machine taken? Pick what you’d do instead, and a swap mid-workout offers these first.": "La màquina està ocupada? Tria quin exercici faries en lloc seu. Si el substitueixes durant l’entrenament, aquestes alternatives apareixeran primer.",
  'Remove “{0}”': "Elimina «{0}»",
  'That’s plenty of backups.': "Ja tens prou alternatives.",
  'Your backups': "Les teves alternatives",
  'Swap to {0}': "Canvia a {0}",
  'Planned backup, same sets and reps': "Alternativa prevista, amb les mateixes sèries i repeticions",
  // --- #583 bodyweight step ---
  'Nothing to add in weight here: it goes up in reps, then sets.': "Aquí no cal augmentar el pes: primer augmenta les repeticions i després les sèries.",
  // --- #523 skip completed ---
