  'Skip completed exercises': "Salta els exercicis completats",
  // --- #551 device link from the phone ---
  'This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.': "Aquesta aplicació no pot confirmar la identitat amb una clau d’accés. Genera el codi en un navegador on hagis iniciat la sessió amb aquest perfil, o bé afegeix-hi abans una contrasenya.",
  // --- Settings → Apple Watch ---
  'Apple Watch': "Apple Watch",
  'Weight': "Pes",
  'Send workouts to the watch': "Envia els entrenaments al rellotge",
  'Open on the watch': "Obre-ho al rellotge",
  "Start a workout on the phone and openGym pops up on your wrist.": "Comença un entrenament al telèfon i openGym apareixerà al teu Apple Watch.",
  "Not allowed": "No autoritzat",
  'Turn on Apple Health and the watch measures your heart rate for every set.': "Activa Apple Health perquè el rellotge mesuri la freqüència cardíaca a cada sèrie.",
  'Tap the wrist when a rest is over': "Vibració al canell quan s’acabi el descans",
  'No Apple Watch paired with this iPhone': "No hi ha cap Apple Watch vinculat a aquest iPhone",
  'openGym is not on your Apple Watch yet. Install it in the Watch app.': "Encara no tens openGym a l’Apple Watch. Instal·la’l des de l’app Watch.",
  'openGym is on your Apple Watch': "openGym està instal·lat a l’Apple Watch",
  'Last heard from the watch: {0}': "Última comunicació del rellotge: {0}",
  'The watch hasn’t checked in yet. Open openGym on it once.': "El rellotge encara no s’ha connectat. Obre-hi openGym una vegada.",
  'Not allowed on the watch. Allow it in the Health app on your iPhone.': "No està permès al rellotge. Permet-ho a l’app Salut de l’iPhone.",
  "Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.": "La freqüència cardíaca es registra durant l’entrenament i al costat de cada sèrie. L’entrenament també es desa a Apple Health. El rellotge només et demanarà permís una vegada.",
  'Apple Health': "Apple Health",
  'Write to Apple Health': "Desa les dades a Apple Health",
  'Open Apple Health': "Obre Apple Health",
  'Workouts and weigh-ins go to Apple Health when you finish or change them.': "Els entrenaments i els registres de pes es desen a Apple Health quan els acabes o els modifiques.",
  'Writing to Apple Health': "S’estan desant les dades a Apple Health",
  'Apple Health permission not granted': "No s’ha concedit el permís per a Apple Health",
  'Could not write to Apple Health': "No s’han pogut desar les dades a Apple Health",
  'Could not remove it from Apple Health': "No s’han pogut eliminar les dades d’Apple Health",
  'Stop writing to Apple Health?': "Vols deixar de desar dades a Apple Health?",
  'What openGym already wrote can stay in Apple Health as your data, or be removed from it.': "Les dades que openGym ja ha desat poden continuar a Apple Health o bé es poden eliminar.",
  'Your workouts in Apple Health': "Els teus entrenaments a Apple Health",
  'openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.': "openGym pot desar tots els entrenaments i registres de pes a Apple Health, i l’Apple Watch pot mostrar-te la freqüència cardíaca mentre entrenes.",
  'Workouts and weigh-ins saved to Apple Health': "Entrenaments i registres de pes desats a Apple Health",
  'Heart rate per set on your Apple Watch': "Freqüència cardíaca de cada sèrie a l’Apple Watch",
  "AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.": "Portes posats els AirPods Pro 3 o els Powerbeats Pro 2? L’iPhone mesura la freqüència cardíaca a cada sèrie, tret que ja ho faci l’Apple Watch.",
  'Switch it off anytime in Settings': "Pots desactivar-ho quan vulguis a Configuració",
  'You can change it anytime in Settings.': "Pots canviar-ho quan vulguis a Configuració.",
  'Last PR': "Últim rècord personal",
