  'Log set': "Registra la sèrie",
  'Next exercise': "Exercici següent",
  'Skip rest': "Salta el descans",
  'Open openGym for the next set': "Obre openGym per començar la sèrie següent",
  'On the watch': "Al rellotge",
  "Fewer things, bigger numbers. Pick what helps you mid-set.": "Menys elements i números més grans. Tria què et va millor veure mentre fas una sèrie.",
  'Exercise animation': "Animació de l’exercici",
  'Heart rate': "Freqüència cardíaca",
