  // --- your bars + warm-up rest default (Discord) ---
  'Your bars': "Les teves barres",
  "Set the bar once for every exercise of a type.": "Indica el pes de la barra una sola vegada per a tots els exercicis d’un mateix tipus.",
  "Your bar for this type, set in Your bars.": "La barra assignada a aquest tipus d’exercici, configurada a «Les teves barres».",
  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "El pes de les barres del teu gimnàs. Per calcular els discos, els exercicis que utilitzen una d’aquestes barres parteixen del seu pes, tret que n’hagis configurat una d’específica per a l’exercici. Els pesos registrats continuaran sent el pes total.",
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': "La majoria dels exercicis de la biblioteca utilitzen «{0}», però alguns utilitzen «{1}». Si vols fer servir una barra curta per a tots, has de configurar totes dues.",
  'Back to the standard bars': "Torna a les barres estàndard",
  "Standard bars. Tap if yours are lighter.": "Barres estàndard. Toca aquí si les teves pesen menys.",
  'The last warm-up still gets the full rest before your first work set.': "Després de l’última sèrie d’escalfament també hi ha el descans complet abans de la primera sèrie de treball.",
  // --- Coach intake: days and session wheels ---
  "Days per week": "Dies a la setmana",
  'Hours': "Hores",
  'h': "h",
