  'Not trained:': "Sense entrenar:",
  'Rounded to whole sets. A set counts fully for its main muscle and partly for the ones that help, so the muscles add up to more than your work sets.': "Arrodonit a sèries senceres. Cada sèrie compta íntegrament per al múscul principal i parcialment per als músculs secundaris. Per això, la suma de les sèries dels músculs pot superar el nombre de sèries de treball.",
