  "App icon": "Icona de l’aplicació",
  'Original': 'Original',
  'Mono': 'Mono',
  "Just for this phone. Some home screens take a moment to catch up.": "Només en aquest telèfon. Algunes pantalles d’inici poden trigar una mica a actualitzar-se.",
  "New icon on its way. It shows up once you leave the app.": "S’està preparant la icona nova. Apareixerà quan surtis de l’aplicació.",
  "The icon could not be changed.": "No s’ha pogut canviar la icona.",
  // Programmes (#159)
