  'Delete programme': "Suprimeix el programa",
  'Deload week': "Setmana de descàrrega",
  'Each adds its own routines, so your plan stays as it is until you start it.': "Cadascun afegeix les seves pròpies rutines, de manera que el teu pla no canvia fins que l'inicies.",
  'Effort for the week': "Esforç de la setmana",
  'Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.': "Si ho deixes en blanc, el pes es determina segons la teva progressió. El %1RM es calcula a partir del teu millor 1RM estimat.",
  'End programme': "Finalitza el programa",
  'End “{0}”?': "Vols finalitzar «{0}»?",
  'Four days. Your progression picks the weights, the effort climbs to RPE 9, then a deload.': "Quatre dies. La teva progressió determina els pesos, l'esforç augmenta fins a RPE 9 i després arriba una setmana de descàrrega.",
  'Heavier means every %1RM goes up {0} points.': "Augmentar el pes vol dir que cada %1RM puja {0} punts.",
  'It is running: ending it brings your plan back. Its routines stay.': "Està en curs: si l'acabes, recuperaràs el teu pla. Les seves rutines es conservaran.",
  'Its routines stay.': "Les seves rutines es conserven.",
  'Its schedule takes over your plan until you end it. Then your plan comes back as it was.': "La seva planificació substitueix el teu pla fins que l'acabis. Després recuperaràs el pla tal com era.",
  'Lighter weights, and its sessions do not count toward progression.': "Els pesos són més lleugers i les seves sessions no compten per a la progressió.",
  'Linear 5×5 style, 12 weeks': "Estil lineal 5×5, 12 setmanes",
  'Log a set first to work this out': "Registra primer una sèrie per poder calcular-ho",
