  'No schedule yet. Put routines on your week or in a loop in Plan, then take it over here.': "Encara no hi ha cap planificació. Afegeix rutines a la setmana o a un bucle des de Pla i després incorpora-les aquí.",
  'Nothing set, progression as usual': "No s'ha configurat res; la progressió continua com sempre",
