  'The schedule in your plan right now becomes this programme’s.': "La planificació actual del teu pla passarà a ser la d'aquest programa.",
  'The week is the calendar week: week 1 is the one you start in. A pause holds it.': "Les setmanes són setmanes naturals: la setmana 1 és aquella en què comences. Si pauses el programa, el recompte de setmanes s'atura.",
