  'For gyms that mix kg and lb. This exercise is shown and typed in it everywhere, plates and steps included. Totals in Stats stay in {0}.': 'Per a gimnasos que combinen kg i lb. Aquest exercici es mostra i s’introdueix sempre en aquesta unitat, inclosos els discos i els increments. Els totals de les estadístiques continuen en {0}.',
