  // --- app tour (components/Tour.jsx) ---
  "A one-minute walk around the app": 'Un recorregut d’un minut per l’aplicació',
  "A practice workout": 'Un entrenament de prova',
  "Backups, imports and syncing with your own server.": 'Còpies de seguretat, importacions i sincronització amb el teu propi servidor.',
  "Body map": 'Mapa corporal',
  "Catch your breath": 'Recupera l’alè',
  "Done with a set? Tick it. Go on, try it.": 'Has acabat una sèrie? Marca-la. Va, prova-ho.',
  "Filter it down": 'Filtra els resultats',
  "Find any exercise": 'Troba qualsevol exercici',
  "Finish line": 'Línia d’arribada',
  "Finish saves the session and moves your weights along. This practice one just quietly disappears.": 'En acabar, la sessió es desa i els pesos progressen. Aquest entrenament de prova simplement desapareix sense desar-se.',
  "Finish the tour?": 'Vols acabar el recorregut?',
  "Finish your workout first, then the tour is all yours.": 'Acaba primer l’entrenament i després podràs fer el recorregut.',
  "Kilos or pounds, and the language you like best.": 'Quilograms o lliures, i l’idioma que prefereixis.',
  "Let’s go": 'Som-hi',
  "Make it yours": 'Personalitza-ho',
  "Muscles at a glance": 'Els músculs d’un cop d’ull',
  "Narrow the list by body part, type or the equipment you have.": 'Filtra la llista per part del cos, tipus d’exercici o material disponible.',
  "No thanks": 'No, gràcies',
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": 'Tria un exercici per veure’n les millors sèries, el màxim estimat i la seva evolució.',
  "Pointing at: {0}": 'Assenyalant: {0}',
  "Practice run": 'Sessió de prova',
  "Programmes and sharing": 'Programes i compartició',
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": 'Aquest botó dona accés als programes, als plans inicials i a l’opció de compartir un pla amb un amic.',
  "Records": 'Rècords',
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": 'El calendari indica quan entrenar i les rutines indiquen què fer. Crea les teves rutines o tria un pla inicial.',
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": 'Cerca milers d’exercicis en el teu idioma. Marca els preferits amb una estrella perquè apareguin al capdamunt.',
  "See which muscles got the work and which still need rest. Tap one for details.": 'Consulta quins músculs han treballat i quins encara necessiten descansar. Toca’n un per veure’n els detalls.',
  "Show me": 'Mostra-m’ho',
  "Show the tour again": 'Torna a mostrar el recorregut',
  "Skip tour": 'Omet el recorregut',
  "Step {0} of {1}": 'Pas {0} de {1}',
  "Swipe a set": 'Llisca una sèrie',
  "Swipe a set sideways to copy or remove it. Its number opens even more.": 'Llisca una sèrie lateralment per copiar-la o eliminar-la. Si toques el número, trobaràs encara més opcions.',
  "The big Start button": 'El gran botó «Comença»',
  "The little body shows what each day works, so leg day can’t hide.": 'La petita figura corporal mostra quins músculs treballes cada dia, perquè no puguis amagar el dia de cames.',
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": 'El temporitzador de descans s’inicia automàticament. Pots afegir-hi temps o ometre’l si et sents amb forces.',
  "The ⋯ menu": 'El menú ⋯',
  "Theme, accent colour and what Home shows.": 'El tema, el color d’accent i el contingut de la pantalla d’inici.',
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": 'Aquest entrenament és fictici i no es desa res. Cada fila és una sèrie: primer el pes i després les repeticions. Toca un número per modificar-lo.',
  "Tick it off": 'Marca-ho',
  "Today at a glance": 'Avui d’un cop d’ull',
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": 'Aquí tens la sessió d’avui. Amb un sol toc ja pots començar a entrenar. Si avui toca descansar, també t’ho indicarà, sense fer-te sentir culpable.',
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": 'Entrena uns dies fixos de la setmana o fes les rutines en bucle, de manera que la següent t’esperi quan acabis.',
  "Want a 1-minute tour?": 'Vols fer un recorregut d’un minut?',
  "Week or rotation": 'Setmana o rotació',
  "We’ll point at the good bits on the real screens. Bail out anytime.": 'T’assenyalarem les funcions més útils a les pantalles reals. Pots sortir-ne quan vulguis.',
  "Workout settings, layouts, notes and extra exercises hide in here.": 'Aquí trobaràs la configuració de l’entrenament, les disposicions, les notes i els exercicis addicionals.',
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": 'Entrenaments, ratxes i tot el pes que has aixecat. Aquest apartat s’omple a mesura que entrenes.',
  "You stopped halfway. Want to see the rest?": 'T’has aturat a mig recorregut. Vols veure la resta?',
  "Your data, your backups": 'Les teves dades i les teves còpies de seguretat',
  "Your progress": 'El teu progrés',
  "Your routines": 'Les teves rutines',
  "You’re set": 'Ja ho tens tot a punt',
