  'Previous year': 'Any anterior',
  'Next year': 'Any següent',
  'Pick a month': 'Tria un mes',
  'Pick a day': 'Tria un dia',
  'With pictures': 'Amb imatges',
  'A small picture next to each exercise, like a plan from the gym.': 'Una imatge petita al costat de cada exercici, com en una fitxa d’entrenament del gimnàs.',
  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": 'Aquesta integració és a l’aplicació mòbil d’openGym: Apple Health a l’iPhone i Health Connect a Android.',
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": 'Els webhooks els envia el teu propi servidor d’openGym, així que en necessites un. Connecta aquest dispositiu al servidor des de l’apartat Compte.',
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": 'Els webhooks estan desactivats en aquest servidor. Afegeix INTEGRATIONS=webhook al fitxer .env i reinicia el servidor.',
  "The MCP server runs next to your own openGym server and reads your data there.": 'El servidor MCP s’executa al costat del teu servidor d’openGym i hi llegeix les dades.',
  "Only what you switch on talks to anything. The rest stays out of your way.": 'Només les integracions que activis es connectaran amb altres serveis. La resta no intervindrà.',
  "Could not reach your server": 'No s’ha pogut contactar amb el servidor',
  "Tap to try again": 'Toca per tornar-ho a provar',
  "Disconnect {0}?": 'Vols desconnectar {0}?',
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": 'openGym deixarà de llegir-hi i d’escriure-hi. Les dades que ja hi ha desat poden quedar-s’hi o bé eliminar-se.',
  "Works with": 'Compatible amb',
  "No extra connection needed: they write to {0}, and openGym reads from there.": 'No cal cap connexió addicional: aquests serveis escriuen a {0} i openGym hi llegeix les dades.',
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": 'No cal cap connexió addicional: aquests serveis escriuen a Apple Health o Health Connect i l’aplicació mòbil d’openGym hi llegeix les dades.',
  "{0} has no direct line to openGym, and it does not need one.": '{0} no té cap connexió directa amb openGym, ni li cal.',
  "How it gets here": 'Com arriben les dades aquí',
  "{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.": '{0} desa les dades a Apple Health a l’iPhone o a Health Connect a Android. openGym les llegeix des d’allà.',
  "What openGym reads": 'Quines dades llegeix openGym',
  "What it does not do": 'Què no fa',
  "Workouts logged in openGym go to the health store, not back into {0} itself.": 'Els entrenaments registrats a openGym s’envien al repositori de salut, però no es tornen a enviar a {0}.',
  "Set up {0}": 'Configura {0}',
  "Install the openGym app on your phone to use this.": 'Per utilitzar aquesta funció, instal·la l’aplicació openGym al mòbil.',
