  "{0} more weeks with a workout earn a freeze.": "{0} setmanes més amb un entrenament et faran guanyar una protecció de ratxa.",
  "Watch on YouTube": "Mira-ho a YouTube",
  "Opens a search for good form": "Obre una cerca per trobar la tècnica correcta",
  "Share with a friend": "Comparteix-ho amb una amistat",
  "As a routine they can do too": "Com a rutina que també puguin fer",
  "Nothing to share in this one.": "No hi ha res per compartir en aquesta rutina.",
  "Link copied. Paste it to a friend.": "Enllaç copiat. Envia'l a una amistat.",
  "That one’s too big for a link, so it goes as a plan file.": "Aquesta rutina és massa gran per compartir-la amb un enllaç; s'enviarà com a fitxer de pla.",
  "Here’s my {0} on openGym 💪": "Aquí tens el meu {0} a openGym 💪",
  "Couldn’t make a link for this one.": "No s'ha pogut crear un enllaç per a aquesta rutina.",
  "A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.": "Un enllaç a «{0}». La teva amistat el toca i afegeix la rutina al seu openGym. La rutina viatja dins l'enllaç, sense cap servidor pel mig.",
  "Include my weights": "Inclou els meus pesos",
  "Off: just sets, reps and rest. They pick their own weights.": "Desactivat: només sèries, repeticions i descans. Cadascú tria els seus pesos.",
  "So they know who it’s from.": "Perquè sàpiguen qui ho envia.",
  "Share link": "Comparteix l'enllaç",
  "From {0}": "De {0}",
  "Added as a new routine. Nothing you already have is touched.": "S'ha afegit com una rutina nova. No s'ha modificat res del que ja tenies.",
  "Add to my routines": "Afegeix-la a les meves rutines",
