  "Mostly late at night. The gym is all yours.": 'Sobretot de matinada. El gimnàs és tot teu.',
  "Early bird": 'Matiner',
  "Most of your sessions started before 9. The sun was still catching up.": "La majoria dels teus entrenaments van començar abans de les 9. El sol encara no s'havia acabat de llevar.",
  "Night owl": 'Mussol nocturn',
  "Most of your sessions started after 8 pm. The quiet gym is your gym.": 'La majoria dels teus entrenaments van començar després de les 20 h. El gimnàs tranquil és el teu gimnàs.',
  "Leg-day loyalist": 'Fidel al dia de cames',
