  "Follows Settings → Workout → Automatic warm-ups.": 'Segueix Configuració → Entrenament → Escalfaments automàtics.',
  "For this workout": 'Per a aquest entrenament',
  "Heavy lifts get more rungs, light ones one or none.": 'Els exercicis amb més pes tenen més esglaons; els més lleugers, un o cap.',
  "It hurts": 'Em fa mal',
  "It hurts, it’s taken, no time, feeling great": 'Em fa mal, està ocupat, no tinc temps, em trobo molt bé',
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Em molesta, així que reduiré el pes per a la resta de l'exercici. Atura't si continua fent mal.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Em molesta, així que faré les sèries que em queden amb un exercici que treballi el mateix múscul des d'un angle menys agressiu.",
  "Keep these warm-ups": 'Conserva aquests escalfaments',
  "Kept. Same warm-ups next time, scaled to your work weight.": 'Conservats. La pròxima vegada es repetiran aquests escalfaments, ajustats al teu pes de treball.',
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Les sèries registrades i la teva rutina es mantenen tal com estan. L'entrenador no és metge ni fisioterapeuta. Si alguna cosa et fa mal, consulta un professional.",
  "Looking at your workout…": 'Analitzant el teu entrenament…',
  "Machine’s taken": 'La màquina està ocupada',
  "My own": 'Personalitzats',
  "New programme “{0}”": 'Programa nou «{0}»',
  "Nothing at {0} {1}: that one starts cold.": 'Cap escalfament amb {0} {1}: aquest exercici comença directament amb el pes de treball.',
  "Nothing could be applied any more.": 'Ja no es podia aplicar cap canvi.',
  "Nothing to change. Carry on as planned.": 'No cal canviar res. Continua segons el pla.',
  "One set less keeps the session doable today and still counts.": "Una sèrie menys farà que avui puguis completar l'entrenament i continuarà comptant.",
  "Only the warm-ups you plan yourself.": 'Només els escalfaments que planifiquis tu mateix.',
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": 'Progressió a partir del pes de treball: més esglaons quan el pes és elevat i menys quan és lleuger.',
  "Remove warm-up {0}": "Elimina l'escalfament {0}",
  "Revise programme “{0}”": 'Revisa el programa «{0}»',
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": 'Rutines, exercicis, sèries i repeticions, escalfaments, programes, horari setmanal, configuració de la progressió i material disponible al teu gimnàs.',
  "Running on empty": 'Sense energia',
  "Saved in the routine, scaled to your work weight": 'Desats a la rutina i ajustats al teu pes de treball',
  "Saved under Plan → Programmes. It starts when you start it.": "Desat a Pla → Programes. Començarà quan tu l'iniciïs.",
  "Short on time": 'Tinc poc temps',
  "Skip the rest of {0}": 'Omet la resta de {0}',
  "Something else": 'Una altra cosa',
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Els esquats, els exercicis de pressió, els rems i similars tenen sèries d'aproximació. Els curls i les elevacions comencen directament amb el pes de treball.",
  "Straight into the work sets.": 'Directament a les sèries de treball.',
  "That workout is over, so these can’t be applied any more.": "Aquest entrenament ja s'ha acabat, així que aquests canvis ja no es poden aplicar.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "L'aplicació calcula l'escalfament a partir del teu pes de treball: més sèries quan el pes és elevat i menys quan és lleuger, utilitzant els discos del teu gimnàs.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": 'El suport està ocupat, així que fes aquest exercici al final. La resta de la sessió no el necessita.',
  "There’s no workout running.": 'No hi ha cap entrenament en curs.',
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": 'Aquests escalfaments es fan abans de les sèries de treball en cada sessió. El seu pes és un percentatge del pes de treball i, per tant, augmenta amb aquest.',
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Aquesta és una demostració, així que no hi ha cap model d'IA al darrere. Al teu propi servidor puc analitzar la sessió i suggerir canvis com aquests.",
  "Warm-up {0}": 'Escalfament {0}',
  "Warm-ups": "Escalfaments",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "Què passa? L'entrenador et proposa alguns canvis per a la part que queda de l'entrenament. Les sèries registrades es mantenen tal com estan.",
  "Where, and what movement hurts? (optional)": "On et fa mal i amb quin moviment? (opcional)",
  "With {0} {1} today: {2}": "Avui, amb {0} {1}: {2}",
  "You can keep training, the answer waits here and in the Coach.": "Pots continuar entrenant; trobaràs la resposta aquí i a l'entrenador.",
  "You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.": "Et sents fort, així que afegim una mica de pes a la barra per a la resta de l'entrenament. No és un nou màxim, només una petita empenta.",
  "Your rows, as a share of the work weight, so they grow with it.": "Les teves remades, com a proporció del pes de treball, perquè augmentin amb aquest pes.",
  "Your workout moved on, so this one no longer fits.": "L'entrenament ha avançat i, per tant, aquesta opció ja no encaixa.",
