  "In the Zepp app, open the openGym watch app’s settings and type in this address and code. The code lasts ten minutes.": "A l'aplicació Zepp, obre la configuració de l'aplicació openGym del rellotge i introdueix-hi aquesta adreça i aquest codi. El codi caduca al cap de deu minuts.",
