  "Wear OS watches talk to the phone through Google Play services, which F-Droid apps leave out. The APK from opengym.ch and the Google Play app have the watch link.": "Els rellotges Wear OS es comuniquen amb el mòbil mitjançant els serveis de Google Play, que no s'inclouen a les aplicacions de F-Droid. L'APK de opengym.ch i l'aplicació de Google Play sí que permeten vincular el rellotge.",
